{
  "name": "静态DDS输出组件",
  "name_en": "Static DDS Output Component",
  "manufacturer": "",
  "description": "这是一个非物理的软件组件，用于在实验控制程序中定义和管理静态DDS样输出通道。它用于设置频率、幅度、相位以及可选的门控开关，并在实验时序中生成、检查和展开相关指令，而不是直接对应某一特定厂商的实体仪器。",
  "description_en": "This is a non-physical software component used to define and manage static DDS-like output channels in an experiment control program. It is used to set frequency, amplitude, phase, and optional gate control, and to generate, validate, and expand timing instructions for experiments rather than representing a specific physical instrument from a particular manufacturer.",
  "actions": [
    {
      "action_name": "auto-disable",
      "description": "禁用静态DDS输出。",
      "description_en": "Disable the static DDS output."
    },
    {
      "action_name": "auto-enable",
      "description": "启用静态DDS输出。",
      "description_en": "Enable the static DDS output."
    },
    {
      "action_name": "auto-setamp",
      "description": "设置静态DDS输出的幅度。",
      "description_en": "Set the amplitude of the static DDS output."
    },
    {
      "action_name": "auto-setfreq",
      "description": "设置静态DDS输出的频率。",
      "description_en": "Set the frequency of the static DDS output."
    },
    {
      "action_name": "auto-setphase",
      "description": "设置静态DDS输出的相位。",
      "description_en": "Set the phase of the static DDS output."
    },
    {
      "action_name": "auto-clock_limit",
      "description": "获取或定义该输出相关的时钟限制。",
      "description_en": "Get or define the clock limit associated with this output."
    },
    {
      "action_name": "auto-trigger_delay",
      "description": "获取或定义触发延迟。",
      "description_en": "Get or define the trigger delay."
    },
    {
      "action_name": "auto-wait_delay",
      "description": "获取或定义等待延迟。",
      "description_en": "Get or define the wait delay."
    },
    {
      "action_name": "auto-get_all_outputs",
      "description": "获取关联的全部输出对象。",
      "description_en": "Get all associated output objects."
    },
    {
      "action_name": "auto-apply_calibration",
      "description": "对输出值应用校准换算。",
      "description_en": "Apply calibration conversion to output values."
    },
    {
      "action_name": "auto-instruction_to_string",
      "description": "将指令转换为字符串表示。",
      "description_en": "Convert an instruction to a string representation."
    },
    {
      "action_name": "auto-add_instruction",
      "description": "向时序中添加输出指令。",
      "description_en": "Add an output instruction to the timing sequence."
    },
    {
      "action_name": "auto-do_checks",
      "description": "执行输出配置和时序检查。",
      "description_en": "Perform output configuration and timing checks."
    },
    {
      "action_name": "auto-offset_instructions_from_trigger",
      "description": "根据触发时间偏移输出指令。",
      "description_en": "Offset output instructions relative to the trigger time."
    },
    {
      "action_name": "auto-get_change_times",
      "description": "获取输出发生变化的时间点。",
      "description_en": "Get the times at which the output changes."
    },
    {
      "action_name": "auto-get_ramp_times",
      "description": "获取斜坡变化的时间区间。",
      "description_en": "Get the time intervals of ramp changes."
    },
    {
      "action_name": "auto-make_timeseries",
      "description": "生成输出时间序列。",
      "description_en": "Generate an output time series."
    },
    {
      "action_name": "auto-expand_timeseries",
      "description": "展开输出时间序列到具体采样点。",
      "description_en": "Expand the output time series into concrete sample points."
    },
    {
      "action_name": "auto-ramp",
      "description": "定义斜坡变化输出。",
      "description_en": "Define a ramped output change."
    },
    {
      "action_name": "auto-sine",
      "description": "定义正弦波输出。",
      "description_en": "Define a sine-wave output."
    },
    {
      "action_name": "auto-sine_ramp",
      "description": "定义正弦型斜坡输出。",
      "description_en": "Define a sine-shaped ramp output."
    },
    {
      "action_name": "auto-sine4_ramp",
      "description": "定义四次正弦型斜坡输出。",
      "description_en": "Define a sine-to-the-fourth ramp output."
    },
    {
      "action_name": "auto-sine4_reverse_ramp",
      "description": "定义反向四次正弦型斜坡输出。",
      "description_en": "Define a reverse sine-to-the-fourth ramp output."
    },
    {
      "action_name": "auto-exp_ramp",
      "description": "定义指数斜坡输出。",
      "description_en": "Define an exponential ramp output."
    },
    {
      "action_name": "auto-exp_ramp_t",
      "description": "定义带时间参数的指数斜坡输出。",
      "description_en": "Define an exponential ramp output with time parameterization."
    },
    {
      "action_name": "auto-piecewise_accel_ramp",
      "description": "定义分段加速度斜坡输出。",
      "description_en": "Define a piecewise-acceleration ramp output."
    },
    {
      "action_name": "auto-square_wave",
      "description": "定义方波输出。",
      "description_en": "Define a square-wave output."
    },
    {
      "action_name": "auto-square_wave_levels",
      "description": "定义具有指定电平的方波输出。",
      "description_en": "Define a square-wave output with specified levels."
    },
    {
      "action_name": "auto-customramp",
      "description": "定义自定义函数斜坡输出。",
      "description_en": "Define a custom-function ramp output."
    },
    {
      "action_name": "auto-constant",
      "description": "定义恒定输出值。",
      "description_en": "Define a constant output value."
    },
    {
      "action_name": "auto-static_value",
      "description": "定义静态输出值。",
      "description_en": "Define a static output value."
    },
    {
      "action_name": "auto-go_high",
      "description": "将数字输出设为高电平。",
      "description_en": "Set the digital output high."
    },
    {
      "action_name": "auto-go_low",
      "description": "将数字输出设为低电平。",
      "description_en": "Set the digital output low."
    },
    {
      "action_name": "auto-repeat_pulse_sequence",
      "description": "定义重复脉冲序列。",
      "description_en": "Define a repeated pulse sequence."
    },
    {
      "action_name": "auto-generate_code",
      "description": "生成实验控制代码或指令数据。",
      "description_en": "Generate experiment control code or instruction data."
    },
    {
      "action_name": "auto-trigger",
      "description": "定义触发事件或触发输出。",
      "description_en": "Define a trigger event or trigger output."
    },
    {
      "action_name": "auto-add_device",
      "description": "添加关联设备或子输出对象。",
      "description_en": "Add an associated device or child output object."
    },
    {
      "action_name": "auto-pulse",
      "description": "定义脉冲输出。",
      "description_en": "Define a pulse output."
    }
  ],
  "tag_hints": [
    "DDS control",
    "static RF output",
    "frequency amplitude phase setting",
    "gated output",
    "labscript experiment sequencing",
    "timing instruction generation",
    "software-defined output"
  ]
}

